package org.sleepwell.app;
import org.json.*;import java.util.*;
/** Historical source evidence; live tokens/permissions/mappings never enter a portable file. */
final class HealthSleepCodec {
 static final int MAX=256*1024;
 static String encode(HealthSleep s){try{JSONArray stages=new JSONArray();for(HealthSleep.Stage p:s.stages)stages.put(new JSONArray().put(p.start).put(p.end).put(p.kind));String out=new JSONObject().put("version",1).put("id",s.id).put("origin",s.origin).put("start",s.start).put("end",s.end).put("modified",s.modified).put("start_offset",s.startOffset==null?JSONObject.NULL:s.startOffset).put("end_offset",s.endOffset==null?JSONObject.NULL:s.endOffset).put("title",s.title).put("notes",s.notes).put("stages",stages).toString();if(out.getBytes(java.nio.charset.StandardCharsets.UTF_8).length>MAX)throw new IllegalArgumentException("Health Connect source evidence is too large.");return out;}catch(JSONException impossible){throw new IllegalArgumentException(impossible);}}
 static HealthSleep read(String text){if(text==null||text.isEmpty())return null;if(text.length()>MAX||text.getBytes(java.nio.charset.StandardCharsets.UTF_8).length>MAX)throw new IllegalArgumentException("Health Connect source evidence is too large.");try{JSONObject j=new JSONObject(text);Set<String> keys=Set.of("version","id","origin","start","end","modified","start_offset","end_offset","title","notes","stages");if(j.length()!=keys.size()||SensorProvenance.whole(j,"version")!=1)throw new JSONException("Invalid Health Connect fields");for(Iterator<String> it=j.keys();it.hasNext();)if(!keys.contains(it.next()))throw new JSONException("Unknown Health Connect field");JSONArray raw=j.getJSONArray("stages");if(raw.length()>HealthSleep.MAX_STAGES)throw new JSONException("Too many sleep stages");List<HealthSleep.Stage> stages=new ArrayList<>();for(int n=0;n<raw.length();n++){JSONArray a=raw.getJSONArray(n);if(a.length()!=3)throw new JSONException("Invalid stage");stages.add(new HealthSleep.Stage(whole(a,0),whole(a,1),Math.toIntExact(whole(a,2))));}return new HealthSleep(SensorProvenance.text(j,"id"),SensorProvenance.text(j,"origin"),SensorProvenance.whole(j,"start"),SensorProvenance.whole(j,"end"),SensorProvenance.whole(j,"modified"),j.isNull("start_offset")?null:Math.toIntExact(SensorProvenance.whole(j,"start_offset")),j.isNull("end_offset")?null:Math.toIntExact(SensorProvenance.whole(j,"end_offset")),SensorProvenance.text(j,"title"),SensorProvenance.text(j,"notes"),stages);}catch(JSONException|ArithmeticException e){throw new IllegalArgumentException("Health Connect source evidence is invalid.",e);}}
 static long whole(JSONArray a,int index)throws JSONException{Object raw=a.get(index);if(!(raw instanceof Number))throw new JSONException("Expected whole timestamp");double d=((Number)raw).doubleValue();long n=((Number)raw).longValue();if(!Double.isFinite(d)||d!=n||Math.abs(d)>9007199254740991d)throw new JSONException("Invalid timestamp");return n;}
 static void validate(JSONObject root)throws JSONException{JSONArray rows=root.getJSONArray("sessions");Set<String> identities=new HashSet<>();for(int n=0;n<rows.length();n++){JSONObject row=rows.getJSONObject(n);try{String encoded=SensorProvenance.text(row,"health_connect");HealthSleep source=read(encoded);if(source==null)continue;if(!identities.add(source.origin+"/"+source.id))throw new JSONException("Duplicate Health Connect source identity");if(!row.getString("source").equals("manual")||!row.getString("origin").equals("imported")||!row.getString("sensor").equals("none")||!row.getString("sound_analysis").isEmpty()||!row.isNull("active_ms")||row.isNull("end")||source.start!=row.getLong("start")||source.end!=row.getLong("end"))throw new JSONException("Health Connect source does not match its historical session");}catch(IllegalArgumentException e){throw new JSONException(e.getMessage());}}}
 private HealthSleepCodec(){}
}
